{
  "name": "off-grid-ai-skills",
  "version": "1.2.0",
  "private": true,
  "description": "Stop babysitting your AI. 49 free skills that make Claude Code, Codex, Cursor and 60+ agents build, test and ship like a senior team.",
  "license": "MIT",
  "scripts": {
    "build": "node scripts/build-manifests.mjs"
  }
}

{
  "name": "off-grid-ai",
  "interface": {
    "displayName": "Off Grid AI skills"
  },
  "plugins": [
    {
      "name": "off-grid-review",
      "source": {
        "source": "local",
        "path": "./review"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "Your AI changes 50 files and you can't tell what broke. You get one page with every screen it touched, before and after, and only the calls that need you."
    },
    {
      "name": "off-grid-testing",
      "source": {
        "source": "local",
        "path": "./testing"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "You fix one bug and two old features break. Every change gets tested by tapping through your app like a real user, with no mocks hiding the breakage."
    },
    {
      "name": "off-grid-codebase",
      "source": {
        "source": "local",
        "path": "./codebase"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "You inherit a codebase nobody fully understands, and every change is a guess. Your AI maps it first, shows you what each change will break, and adds tests before it touches anything risky."
    },
    {
      "name": "off-grid-design",
      "source": {
        "source": "local",
        "path": "./design"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "Most vibe-coded apps look the same. Every screen has to clear a real design bar and reuse your best components, and a note on one screen fixes all of them."
    },
    {
      "name": "off-grid-cto",
      "source": {
        "source": "local",
        "path": "./cto"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "No CTO? Your AI picks what's urgent, tells you when you're wrong, keeps building overnight and picks up any old chat where you left it."
    },
    {
      "name": "off-grid-launch",
      "source": {
        "source": "local",
        "path": "./launch"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "It worked on your laptop and broke on your phone. Every release gets tried on real phones first, then ships with notes people actually read."
    },
    {
      "name": "off-grid-growth",
      "source": {
        "source": "local",
        "path": "./growth"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "Your landing page reads like ChatGPT wrote it. With these, your copy sounds like a person, it sells, and AI search starts naming you."
    },
    {
      "name": "off-grid-revenue",
      "source": {
        "source": "local",
        "path": "./revenue"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "You have Stripe, analytics and store numbers but no idea what to change. You get the three moves that should grow revenue most, and big calls laid out on one page."
    },
    {
      "name": "off-grid-games",
      "source": {
        "source": "local",
        "path": "./games"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity",
      "description": "Making a game alone with AI? You get a director, an art director and a QA team that playtests every scene."
    }
  ]
}

{
  "//": "Hygiene tsconfig flags - WEB. These three flags are the compiler half of the AI-dead-code net (the eslint rules are the other half). bootstrap.sh MERGES these into your existing tsconfig.json compilerOptions (it does not replace your tsconfig). Shown here as a standalone fragment for reference and for a manual merge.",
  "compilerOptions": {
    "//allowUnreachableCode": "false = the compiler ERRORS on code after a return/throw/break. Catches dead code an AI left behind.",
    "allowUnreachableCode": false,
    "//noUnusedLocals": "true = an unused local variable is a compile error.",
    "noUnusedLocals": true,
    "//noUnusedParameters": "true = an unused function parameter is a compile error (prefix with _ to intentionally ignore).",
    "noUnusedParameters": true
  }
}

{
  "//": "Hygiene tsconfig flags - REACT NATIVE. These three flags are the compiler half of the AI-dead-code net (the eslint rules are the other half). bootstrap.sh MERGES these into your existing tsconfig.json compilerOptions (it does not replace your tsconfig). Shown here as a standalone fragment for reference and for a manual merge.",
  "compilerOptions": {
    "//allowUnreachableCode": "false = the compiler ERRORS on code after a return/throw/break. Catches dead code an AI left behind.",
    "allowUnreachableCode": false,
    "//noUnusedLocals": "true = an unused local variable is a compile error.",
    "noUnusedLocals": true,
    "//noUnusedParameters": "true = an unused function parameter is a compile error (prefix with _ to intentionally ignore).",
    "noUnusedParameters": true
  }
}
